{
"milestones": [
{
"id": "m1",
"title": "Add FORMAT_RFC3339_STRICT constant",
"requests": [
"R2"
],
"requirement": "I need a new format constant that uses the 'T' separator for strict RFC3339 compliance, distinct from the existing space-separated one.",
"observable": "import arrow; assert 'T' in arrow.FORMAT_RFC3339_STRICT; arw = arrow.utcnow(); fmted = arw.format(arrow.FORMAT_RFC3339_STRICT); assert 'T' in fmted",
"public_names": [
"FORMAT_RFC3339_STRICT"
],
"requires": [],
"why_requires": ""
},
{
"id": "m2",
"title": "Migrate internal timezone handling to ZoneInfo and fix utcnow deprecation",
"requests": [
"R4",
"R7"
],
"requirement": "Replace internal usage of pytz/dateutil tz with standard library zoneinfo.ZoneInfo and datetime.UTC to remove deprecation warnings and modernize dependencies. Specifically, replace datetime.utcnow() calls and migrate TzinfoParser to use ZoneInfo where appropriate or fall back to dateutil if necessary but expose standard types.",
"observable": "import warnings; with warnings.catch_warnings(): warnings.simplefilter('error'); import arrow; aw = arrow.utcnow(); assert aw.tzinfo is not None; tz_str = 'US/Pacific'; aw2 = arrow.now(tz_str); assert hasattr(aw2.tzinfo, 'key') or str(type(aw2.tzinfo)) == \"<class 'zoneinfo.ZoneInfo'>\"",
"public_names": [
"utcnow",
"now",
"_get_tzinfo"
],
"requires": [],
"why_requires": ""
},
{
"id": "m3",
"title": "Add week_start parameter to floor and ceil methods",
"requests": [
"R1"
],
"requirement": "The floor() and ceil() methods should accept an optional week_start parameter (0-6) to define which day starts the week when flooring/ceiling to weeks.",
"observable": "import arrow; a = arrow.Arrow(2023, 10, 5); # Thursday m3_res_floor_mon = a.floor('week', week_start=1); # Should be Monday Oct 2 m3_res_ceil_sun = a.ceil('week', week_start=0); # Should be Sunday Oct 8 assert m3_res_floor_mon.day == 2; assert m3_res_ceil_sun.day == 8",
"public_names": [
"floor",
"ceil"
],
"requires": [
"m2"
],
"why_requires": "floor and ceil operate on dates/times. While they don't directly call _get_tzinfo for simple date arithmetic, their robustness relies on the underlying Arrow object having consistent timezone handling (established in m2) if timezone-aware weeks are involved or if the implementation delegates to span logic which may use tz info. More critically, this milestone builds on the clean state established by m2 ensuring no deprecation noise interferes with test verification of the new feature."
},
{
"id": "m4",
"title": "Add check_imaginary parameter to shift method",
"requests": [
"R6"
],
"requirement": "The shift() method needs a check_imaginary parameter (default True) to optionally skip DST/imaginary time checks for performance when the user knows no such transitions occur.",
"observable": "import arrow; a = arrow.Arrow(2023, 3, 12, 2, 30, tz='US/Eastern'); # Imaginary time try: a.shift(hours=1, check_imaginary=True): raise AssertionError("
}
